def shortest_path(start, goal):
    queue = deque([[start]])
    visited = {start}
    while queue:
        path = queue.popleft()
        if path[-1] == goal:
            return path
        for nxt in links[path[-1]]:
            if nxt not in visited:
                visited.add(nxt)
                queue.append(path + [nxt])

