"""netmodel.py - the object model shared by the netkit tools."""
import ipaddress
import json
from dataclasses import asdict, dataclass, field
from enum import Enum


class PortState(Enum):
    OPEN = "open"
    CLOSED = "closed"
    FILTERED = "filtered"


@dataclass(frozen=True, order=True)
class Port:
    number: int
    proto: str = "tcp"

    def __post_init__(self):
        if not 1 <= self.number <= 65535:
            raise ValueError(f"port out of range: {self.number}")
        if self.proto not in ("tcp", "udp"):
            raise ValueError(f"unknown protocol: {self.proto!r}")

    def __str__(self):
        return f"{self.number}/{self.proto}"

    @classmethod
    def parse(cls, text):
        number, _, proto = text.partition("/")
        return cls(int(number), proto or "tcp")


@dataclass
class ScanResult:
    port: Port
    state: PortState
    rtt_ms: float | None = None

    @property
    def is_open(self):
        return self.state is PortState.OPEN


@dataclass(order=True)
class Host:
    ip: ipaddress.IPv4Address
    name: str = field(default="", compare=False)
    results: dict = field(default_factory=dict, compare=False, repr=False)

    def __post_init__(self):
        self.ip = ipaddress.IPv4Address(self.ip)

    def record(self, result):
        self.results[result.port] = result

    @property
    def open_ports(self):
        return sorted(p for p, r in self.results.items() if r.is_open)

    def __str__(self):
        label = f" ({self.name})" if self.name else ""
        return f"{self.ip}{label}"


class Subnet:
    """An IPv4 network that behaves like a collection of its usable host addresses."""

    def __init__(self, cidr):
        self.network = ipaddress.IPv4Network(cidr, strict=False)

    def __contains__(self, item):
        try:
            return ipaddress.IPv4Address(getattr(item, "ip", item)) in self.network
        except ValueError:
            return False

    def __iter__(self):
        return iter(self.network.hosts())

    def __len__(self):
        n = self.network
        return n.num_addresses - 2 if n.prefixlen < 31 else n.num_addresses

    def __eq__(self, other):
        return isinstance(other, Subnet) and self.network == other.network

    def __hash__(self):
        return hash(self.network)

    def __lt__(self, other):
        return self.network < other.network

    def __repr__(self):
        return f"Subnet({str(self.network)!r})"

    def __str__(self):
        return str(self.network)


class Inventory:
    """Hosts keyed by IP address, iterated in address order."""

    def __init__(self, hosts=()):
        self._hosts = {}
        for host in hosts:
            self.add(host)

    def add(self, host):
        if host.ip in self._hosts:
            raise ValueError(f"duplicate host: {host.ip}")
        self._hosts[host.ip] = host

    def __len__(self):
        return len(self._hosts)

    def __iter__(self):
        return iter(sorted(self._hosts.values()))

    def __getitem__(self, ip):
        return self._hosts[ipaddress.IPv4Address(ip)]

    def __contains__(self, ip):
        try:
            return ipaddress.IPv4Address(getattr(ip, "ip", ip)) in self._hosts
        except ValueError:
            return False

    def in_subnet(self, subnet):
        return (h for h in self if h in subnet)

    def open_ports(self):
        for host in self:
            for port in host.open_ports:
                yield host, port

    def to_json(self):
        rows = [{"ip": str(h.ip), "name": h.name, "open": [str(p) for p in h.open_ports]} for h in self]
        return json.dumps(rows, indent=2)

