function describeUrl(href) {
  const url = new URL(href);
  const scheme = url.protocol.slice(0, -1);
  return {
    scheme,
    host: url.hostname,
    port: Number(url.port) || (scheme === 'https' ? 443 : 80),
    path: url.pathname,
    query: Object.fromEntries(url.searchParams),
    fragment: url.hash.slice(1),
  };
}
