const SERVICES = { 22: 'ssh', 53: 'dns', 80: 'http', 443: 'https', 445: 'smb' };

export function serviceName(port) {
  return SERVICES[port] ?? 'unknown';
}

export default function isPrivate(ip) {
  const [a, b] = ip.split('.').map(Number);
  return a === 10 || (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168);
}

// legacy.cjs: the .cjs extension forces CommonJS, whatever package.json says
