// emitter.js: EventEmitter calls listeners synchronously, in registration order
import { EventEmitter } from 'node:events';

class Monitor extends EventEmitter {
  report(host, up) {
    this.emit('result', host, up);
    if (!up) this.emit('down', host);
  }
}

const monitor = new Monitor();
monitor.on('result', (host, up) => console.log(`result ${host} ${up ? 'up' : 'DOWN'}`));
monitor.once('down', (host) => console.log(`ALERT first outage: ${host}`));

console.log('before');
monitor.report('192.168.1.1', true);
monitor.report('192.168.1.60', false);
monitor.report('192.168.1.70', false);
console.log('after; down listeners left:', monitor.listenerCount('down'));

monitor.emit('error', new Error('probe socket failed')); // nobody listens for 'error'
console.log('never printed');

