// test/api.test.js: start the whole app on a free port with a throwaway data file, then use it like a client
import { describe, it, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, writeFile, readFile, rm } from 'node:fs/promises';
import { once } from 'node:events';
import { tmpdir } from 'node:os';
import net from 'node:net';
import path from 'node:path';

const impl = process.env.APP === 'http' ? '../src/http-app.js' : '../src/app.js';
const { createApp } = await import(impl);

let ctx, base, dir, dataFile, listener, openPort;

async function freePort() { // ask the OS for a port, then release it: nothing listens there afterwards
  const s = net.createServer().listen(0, '127.0.0.1');
  await once(s, 'listening');
  const { port } = s.address();
  s.close();
  return port;
}

before(async () => {
  listener = net.createServer((socket) => socket.end()); // a service for the checker to find
  listener.listen(0, '127.0.0.1');
  await once(listener, 'listening');
  openPort = listener.address().port;

  dir = await mkdtemp(path.join(tmpdir(), 'dashboard-test-'));
  dataFile = path.join(dir, 'devices.json');
  await writeFile(dataFile, JSON.stringify({
    nextId: 3,
    devices: [
      { id: 1, name: 'listener', ip: '127.0.0.1', port: openPort, type: 'server', notes: '' },
      { id: 2, name: 'router', ip: '192.168.1.1', port: 80, type: 'router', notes: 'R&D <lab>' },
    ],
  }));
  ctx = await createApp({ dataFile, timeoutMs: 300, log: () => {} }); // no sweeps: tests call checks explicitly
  ctx.server.listen(0, '127.0.0.1');
  await once(ctx.server, 'listening');
  base = `http://127.0.0.1:${ctx.server.address().port}`;
});

after(async () => {
  ctx.monitor.stop();
  ctx.server.close();
  listener.close();
  await rm(dir, { recursive: true, force: true });
});

const get = (p) => fetch(base + p);
const send = (method, p, body) =>
  fetch(base + p, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });

describe('reading devices', () => {
  it('lists every device with a status and a count header', async () => {
    const res = await get('/api/devices');
    assert.equal(res.status, 200);
    assert.equal(res.headers.get('x-total-count'), '2');
    const list = await res.json();
    assert.deepEqual(list.map((d) => d.name), ['listener', 'router']);
    assert.equal(list[0].status.state, 'unknown');
  });

  it('filters by type and searches name or ip', async () => {
    const names = async (q) => (await (await get(`/api/devices?${q}`)).json()).map((d) => d.name);
    assert.deepEqual(await names('type=router'), ['router']);
    assert.deepEqual(await names('q=LIST'), ['listener']);
    assert.deepEqual(await names('q=192.168'), ['router']);
  });

  it('answers 404 in JSON for an unknown id or route', async () => {
    const res = await get('/api/devices/99');
    assert.equal(res.status, 404);
    assert.deepEqual(await res.json(), { error: 'device 99 not found' });
    assert.equal((await get('/api/nothing')).status, 404);
  });
});

describe('changing devices', () => {
  it('creates a device: 201, Location, saved to the file', async () => {
    const res = await send('POST', '/api/devices', { name: 'pi', ip: '127.0.0.1', port: openPort, type: 'server' });
    assert.equal(res.status, 201);
    const pi = await res.json();
    assert.equal(res.headers.get('location'), `/api/devices/${pi.id}`);
    const saved = JSON.parse(await readFile(dataFile, 'utf8'));
    assert.equal(saved.nextId, pi.id + 1);
    assert.ok(saved.devices.some((d) => d.name === 'pi'));
  });

  it('rejects bad fields with 422 and one message per field', async () => {
    const res = await send('POST', '/api/devices', { name: '', ip: '8.8.8.8', port: 70000 });
    assert.equal(res.status, 422);
    const body = await res.json();
    assert.deepEqual(Object.keys(body.fields).sort(), ['ip', 'name', 'port']);
    assert.match(body.fields.ip, /LAN/);
  });

  it('rejects a duplicate name (409), broken JSON (400) and form bodies (415)', async () => {
    assert.equal((await send('POST', '/api/devices', { name: 'Router', ip: '192.168.1.2' })).status, 409);
    const broken = await fetch(`${base}/api/devices`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{"name":' });
    assert.equal(broken.status, 400);
    const form = await fetch(`${base}/api/devices`, { method: 'POST', body: new URLSearchParams({ name: 'x', ip: '10.0.0.9' }) });
    assert.equal(form.status, 415);
  });

  it('replaces with PUT, deletes with DELETE', async () => {
    const put = await send('PUT', '/api/devices/2', { name: 'router', ip: '192.168.1.254', port: 443, type: 'router', notes: 'R&D <lab>' });
    assert.equal(put.status, 200);
    assert.equal((await put.json()).port, 443);
    const created = await (await send('POST', '/api/devices', { name: 'temp', ip: '10.0.0.9' })).json();
    assert.equal((await fetch(`${base}/api/devices/${created.id}`, { method: 'DELETE' })).status, 204);
    assert.equal((await get(`/api/devices/${created.id}`)).status, 404);
    assert.equal((await send('PUT', `/api/devices/${created.id}`, { name: 'temp', ip: '10.0.0.9' })).status, 404);
  });
});

describe('checks, status and feeds', () => {
  it('reports up for a listening port and down for a closed one', async () => {
    const up = await (await fetch(`${base}/api/devices/1/check`, { method: 'POST' })).json();
    assert.equal(up.state, 'up');
    const closed = await (await send('POST', '/api/devices', { name: 'closed', ip: '127.0.0.1', port: await freePort() })).json();
    const down = await (await fetch(`${base}/api/devices/${closed.id}/check`, { method: 'POST' })).json();
    assert.equal(down.state, 'down');
    assert.equal(down.error, 'ECONNREFUSED');
  });

  it('summarises states and exposes a data version', async () => {
    const s = await (await get('/api/status')).json();
    assert.equal(s.total, s.devices.length);
    assert.equal(s.up + s.down + s.unknown, s.total);
    assert.ok(s.version > 0, 'version grows with every change');
    assert.ok(s.devices.some((d) => d.id === 1 && d.state === 'up'));
  });

  it('exports escaped XML', async () => {
    const res = await get('/api/devices.xml');
    assert.match(res.headers.get('content-type'), /^application\/xml/);
    const xml = await res.text();
    assert.ok(xml.startsWith('<?xml version="1.0" encoding="UTF-8"?>'));
    assert.ok(xml.includes('<notes>R&amp;D &lt;lab&gt;</notes>'));
    assert.ok(!xml.includes('<lab>'));
  });

  it('publishes events as JSON and RSS', async () => {
    const events = await (await get('/api/events')).json();
    assert.ok(events.some((e) => e.kind === 'added' && e.text.startsWith('pi ')));
    assert.ok(events.some((e) => e.kind === 'removed'));
    const res = await get('/feed.rss');
    assert.match(res.headers.get('content-type'), /^application\/rss\+xml/);
    const rss = await res.text();
    assert.ok(rss.includes('<rss version="2.0">') && rss.includes('was added</title>'));
  });

  it('serves the front end', async () => {
    const res = await get('/');
    assert.match(res.headers.get('content-type'), /^text\/html/);
    assert.match(await res.text(), /<title>LAN dashboard<\/title>/);
    const js = await get('/api.js'); // a file whose name starts with "api": static, not an API route
    assert.match(js.headers.get('content-type'), /javascript/);
  });
});

/* public/style.css: tokens first, then layout, then components */
*, *::before, *::after { box-sizing: border-box; }

:root {
  color-scheme: light dark;
  --bg: #f5f6f8;
  --panel: #ffffff;
  --text: #1c2430;
  --muted: #5d6b7c;
  --line: #d7dde5;
  --accent: #2557c7;
  --up: #1f7a3d;
  --down: #b42318;
  --unknown: #6b7280;
  --radius: 10px;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #11151b; --panel: #1a2029; --text: #e6ebf2; --muted: #9aa7b8;
    --line: #2c3542; --accent: #7aa2ff; --up: #4cc27a; --down: #ff7a6b; --unknown: #9ca3af;
  }
}
:root[data-theme="dark"] {
  --bg: #11151b; --panel: #1a2029; --text: #e6ebf2; --muted: #9aa7b8;
  --line: #2c3542; --accent: #7aa2ff; --up: #4cc27a; --down: #ff7a6b; --unknown: #9ca3af;
}

body {
  margin: 0;
  font: 16px/1.5 system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
}
h1, h2, h3 { line-height: 1.2; margin: 0 0 0.5rem; }
h2 { font-size: 1.15rem; }
code { font: 0.95em ui-monospace, Menlo, monospace; }
a { color: var(--accent); }

.top {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.5rem 1.5rem;
  padding: 1rem clamp(1rem, 3vw, 2rem);
  background: var(--panel); border-bottom: 1px solid var(--line);
}
.top p { margin: 0; color: var(--muted); }
.top button { margin-left: auto; }

.banner {
  margin: 0; padding: 0.6rem clamp(1rem, 3vw, 2rem);
  background: var(--down); color: #fff; font-weight: 600;
}

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 20rem;
  gap: 1.5rem;
  padding: 1.5rem clamp(1rem, 3vw, 2rem);
}
@media (max-width: 52rem) {
  .layout { grid-template-columns: minmax(0, 1fr); }
}

.filters { display: flex; flex-wrap: wrap; gap: 0.75rem; margin-bottom: 1rem; }
.filters label { display: flex; flex-direction: column; font-size: 0.85rem; color: var(--muted); }

.grid {
  list-style: none; margin: 0; padding: 0;
  display: grid; gap: 1rem;
  grid-template-columns: repeat(auto-fill, minmax(15rem, 1fr));
}
.card article {
  height: 100%; padding: 0.9rem 1rem;
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
  border-left: 6px solid var(--state);
}
.card { --state: var(--unknown); }
.card[data-state="up"] { --state: var(--up); }
.card[data-state="down"] { --state: var(--down); }
.card header { display: flex; justify-content: space-between; align-items: center; gap: 0.5rem; }
.card p { margin: 0.25rem 0; }
.card .notes, .card .detail { color: var(--muted); font-size: 0.9rem; }
.card .notes:empty { display: none; }
.badge {
  padding: 0.1rem 0.55rem; border-radius: 999px;
  background: var(--state); color: var(--panel);
  font-size: 0.8rem; font-weight: 700; text-transform: uppercase;
}
.actions { display: flex; flex-wrap: wrap; gap: 0.4rem; margin-top: 0.6rem; }

aside section {
  padding: 1rem; margin-bottom: 1.5rem;
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
}
#device-form label { display: block; margin-top: 0.6rem; font-size: 0.9rem; }
#device-form input, #device-form select, #device-form textarea { width: 100%; }
input, select, textarea, button { font: inherit; color: inherit; }
input, select, textarea {
  padding: 0.35rem 0.5rem; background: var(--bg);
  border: 1px solid var(--line); border-radius: 6px;
}
[aria-invalid="true"] { border-color: var(--down); outline: 1px solid var(--down); }
.error { margin: 0.15rem 0 0; min-height: 1.2em; color: var(--down); font-size: 0.85rem; }
.buttons { display: flex; gap: 0.5rem; margin-top: 0.75rem; }
button {
  padding: 0.35rem 0.8rem; cursor: pointer; white-space: nowrap;
  background: var(--panel); border: 1px solid var(--line); border-radius: 6px;
}
button[type="submit"] { background: var(--accent); border-color: var(--accent); color: var(--panel); }
button.danger { color: var(--down); }
button:disabled { opacity: 0.5; cursor: progress; }
button:focus-visible, input:focus-visible, select:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.events { margin: 0; padding-left: 1.2rem; font-size: 0.9rem; }
